public int search(int[] nums, int target) {
    int start = 0;
    int end = nums.length - 1;

    while (start < end) {
        int mid = start + (end - start) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[start] <= nums[mid]) {
            if (nums[start] <= target && target < nums[mid]) {
                end = mid - 1;
            } else {
                start = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[end]) {
                start = mid + 1;
            } else {
                end = mid - 1;
            }
        }
    }

    if (nums[start] == target) {
        return start;
    }

    return -1;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the smallest 5% of elements
    int smallest5Percent = (int) (arr.length * 0.05);
    int smallest5PercentSum = 0;
    for (int i = 0; i < smallest5Percent; i++) {
        smallest5PercentSum += arr[i];
    }

    // Calculate the largest 5% of elements
    int largest5Percent = (int) (arr.length * 0.05);
    int largest5PercentSum = 0;
    for (int i = arr.length - 1; i >= arr.length - largest5Percent; i--) {
        largest5PercentSum += arr[i];
    }

    // Calculate the mean of the remaining elements
    int sum = 0;
    for (int i = smallest5Percent; i < arr.length - largest5Percent; i++) {
        sum += arr[i];
    }
    double mean = (double) sum / (arr.length - 2 * smallest5Percent);

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
}

