public static int squarePermutations(int[] A) {
    int[] list = new int[A.length];
    for (int i = 0; i < A.length; i++) {
        list[i] = A[i];
    }

    int count = 0;
    do {
        boolean isSquare = true;
        for (int i = 0; i < A.length - 1; i++) {
            if (list[i] + list[i + 1] != 0 && Math.sqrt(list[i] + list[i + 1]) != Math.floor(Math.sqrt(list[i] + list[i + 1]))) {
                isSquare = false;
                break;
            }
        }
        if (isSquare) {
            count++;
        }
    } while (nextPermutation(list));

    return count;
}

static boolean nextPermutation(int[] list) {
    int i = list.length - 1;
    while (i > 0 && list[i - 1] >= list[i]) {
        i--;
    }
    if (i == 0) {
        return false;
    }

    int j = list.length - 1;
    while (list[i - 1] >= list[j]) {
        j--;
    }

    swap(list, i - 1, j);

    int k = list.length - 1;
    while (i < k) {
        swap(list, i++, k--);
    }

    return true;
}

static void swap(int[] list, int i, int j) {
    int tmp = list[i];
    list[i] = list[j];
    list[j] = tmp;
}

