        digits[i] = i;
    }
    for (int i = 0; i < n; i++) {
        int digit = n % 10;
        n /= 10;
        if (digit == 0) {
            continue;
        }
        int index = digit - 1;
        if (index == 0) {
            index = 9;
        }
        int temp = digits[index];
        digits[index] = digits[digit - 1];
        digits[digit - 1] = temp;
    }
