                Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == uglyNumbers[i2] * 2) {
            i2++;
        }
        if (nextUglyNumber == uglyNumbers[i3] * 3) {
            i3++;
        }
        if (nextUglyNumber == uglyNumbers[i5] * 5) {
            i5++;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int max = 0, start = 0, end = 0;
    for (int center = 0; center < s.length(); center++) {
        int i = center, j = center + 1;
        int halfLen = 0;
        while (i >= 0 && j < s.length() && s.charAt(i) == s.charAt(j)) {
            halfLen++;
            i--;
            j++;
        }
        int currentLength = halfLen * 2;
        if (currentLength > max) {
            max = currentLength;
            start = center - halfLen + 1;
            end = center + halfLen;
        }
    }
    return end - start + 1;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (!uniqueNums.contains(num)) {
            uniqueNums.add(num);
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            count++;
        }
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        reversedSentence.append(reversedWord.toString());
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}
